function initLogin() {
  const ll = document.getElementById('login-logo');
  if (ll && typeof AIRCON_LOGO_B64 !== 'undefined') ll.src = AIRCON_LOGO_B64;

  try {
    const saved = JSON.parse(sessionStorage.getItem('aircon_user') || 'null');
    if (saved && saved.name) {
      currentUser = saved;
      document.getElementById('login-overlay').style.display = 'none';
      applyUserRole();
      return;
    }
  } catch {}

  // Populate name dropdown from technicians DB
  const sel = document.getElementById('login-name');
  if (sel && sel.options.length <= 1) {
    getTechniciansDB().forEach(t => {
      const full = typeof t === 'string' ? t : '';
      if (!full) return;
      const name = full.split(/\s{2,}/)[0] || full;
      const opt = document.createElement('option');
      opt.value = name; opt.textContent = name;
      sel.appendChild(opt);
    });
  }
  document.getElementById('login-overlay').style.display = 'flex';
}

