function aiAddPart(partNo, desc, qty) {
  // Find empty part row or add new one
  const rows = document.querySelectorAll('[id^="part-row-"]');
  let added = false;
  for (const row of rows) {
    const idNum = row.id.split('-').pop();
    const pnEl = document.getElementById('part-no-' + idNum);
    if (pnEl && !pnEl.value.trim()) {
      pnEl.value = partNo;
      const descEl = document.getElementById('part-desc-' + idNum);
      if (descEl) descEl.value = desc;
      const qtyEl = document.getElementById('part-qty-' + idNum);
      if (qtyEl) qtyEl.value = qty;
      added = true;
      break;
    }
  }
  if (!added) {
    if (typeof addPartRow === 'function') {
      addPartRow();
      setTimeout(() => {
        const newRows = document.querySelectorAll('[id^="part-row-"]');
        const last = newRows[newRows.length - 1];
        if (last) {
          const id = last.id.split('-').pop();
          const pnEl = document.getElementById('part-no-' + id);
          if (pnEl) pnEl.value = partNo;
          const descEl = document.getElementById('part-desc-' + id);
          if (descEl) descEl.value = desc;
          const qtyEl = document.getElementById('part-qty-' + id);
          if (qtyEl) qtyEl.value = qty;
        }
      }, 100);
    }
  }
  snack(`✔ Added: ${partNo || desc}`);
}

function renderSuperWorkTypes(reports) {
  const tbody = document.getElementById('sup-work-body');
  const tbody2 = document.getElementById('sup-parts-by-type-body');
  if (!tbody) return;

  // Group by job type
  const byType = {};
  reports.forEach(r => {
    const type = (r.type || r.jobType || 'Unknown').trim() || 'Unknown';
    if (!byType[type]) byType[type] = { count:0, units:new Set(), reg:0, ot:0, parts:{} };
    byType[type].count++;
    if (r.unit) byType[type].units.add(r.unit);

    // Sum hours
    (r.techs||[]).forEach(t => {
      const h = (typeof calcHours === 'function') ? calcHours(t.timeIn||t.start, t.timeOut||t.end) : 0;
      if (t.ot) byType[type].ot += h; else byType[type].reg += h;
    });

    // Collect parts
    (r.parts||[]).forEach(p => {
      if (!p.partNo) return;
      if (!byType[type].parts[p.partNo]) byType[type].parts[p.partNo] = { desc: p.desc||'', qty:0 };
      byType[type].parts[p.partNo].qty += parseInt(p.qty||1);
    });
  });

  const rows = Object.entries(byType).sort((a,b) => b[1].count - a[1].count);
  const f = n => n > 0 ? n.toFixed(1) : '—';

  // Work types summary table
  tbody.innerHTML = rows.length ? rows.map(([type, d]) => {
    const topParts = Object.entries(d.parts)
      .sort((a,b) => b[1].qty - a[1].qty).slice(0,3)
      .map(([pn, p]) => `${pn} (×${p.qty})`).join(', ');
    const typeColor = type === 'F/S' ? '#1a5276' : type === 'HVAC' ? '#145a32' : '#4a235a';
    return `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:8px 10px">
        <span style="background:${typeColor};color:#fff;border-radius:4px;padding:2px 10px;font-size:11px;font-weight:700">${escapeHtml(type)}</span>
      </td>
      <td style="padding:8px 10px;text-align:center;font-weight:700;font-size:15px">${d.count}</td>
      <td style="padding:8px 10px;font-size:12px;color:var(--muted)">${[...d.units].slice(0,5).join(', ')}${d.units.size>5?'…':''}</td>
      <td style="padding:8px 10px;text-align:center;background:#f0fff4;font-weight:600">${f(d.reg)}</td>
      <td style="padding:8px 10px;text-align:center;background:#fff8f0;font-weight:600;color:#b35400">${f(d.ot)}</td>
      <td style="padding:8px 10px;font-size:11px;color:var(--muted)">${topParts || '—'}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="6" style="padding:16px;text-align:center;color:var(--muted)">No data</td></tr>';

  // Parts by type table
  if (!tbody2) return;
  const partsByType = [];
  rows.forEach(([type, d]) => {
    Object.entries(d.parts).sort((a,b)=>b[1].qty-a[1].qty).forEach(([pn, p]) => {
      partsByType.push({ type, pn, desc: p.desc, qty: p.qty,
        reports: reports.filter(r => (r.type||r.jobType||'Unknown') === type && (r.parts||[]).some(pp=>pp.partNo===pn)).length
      });
    });
  });

  tbody2.innerHTML = partsByType.length ? partsByType.map(p => {
    const typeColor = p.type === 'F/S' ? '#1a5276' : p.type === 'HVAC' ? '#145a32' : '#4a235a';
    return `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:6px 10px">
        <span style="background:${typeColor};color:#fff;border-radius:4px;padding:1px 8px;font-size:10px;font-weight:700">${escapeHtml(p.type)}</span>
      </td>
      <td style="padding:6px 10px;font-weight:600;font-family:monospace;font-size:12px">${escapeHtml(p.pn)}</td>
      <td style="padding:6px 10px;font-size:12px">${escapeHtml(p.desc||'')}</td>
      <td style="padding:6px 10px;text-align:center;font-weight:700;font-size:14px">${p.qty}</td>
      <td style="padding:6px 10px;text-align:center;color:var(--muted)">${p.reports}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="5" style="padding:16px;text-align:center;color:var(--muted)">No parts data</td></tr>';
}

