function ihIsExpiringSoon(hydroVal) {
  if (!hydroVal) return false;
  const [yr, mo] = hydroVal.split('-').map(Number);
  if (!yr || !mo) return false;
  const hydroDate = new Date(yr, mo - 1, 1);
  const sixMonths = new Date();
  sixMonths.setMonth(sixMonths.getMonth() + 6);
  return hydroDate <= sixMonths;
}

