function openDbSuggestMenu() {
  const types = [
    ['parts','🔧 Parts'],['technicians','👷 Technicians'],
    ['trucks','🚛 Trucks'],['equipment','🚜 Equipment']
  ];
  const m = document.createElement('div');
  m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9000;display:flex;align-items:flex-end;justify-content:center';
  const grid = types.map(([t,label]) =>
    `<button onclick="openSuggestDialog('${t}');document.getElementById('db-suggest-modal').remove()"
      style="padding:12px;background:#1a3560;color:#fff;border:none;border-radius:8px;font-size:14px;cursor:pointer">${label}</button>`
  ).join('');
  m.id = 'db-suggest-modal';
  m.innerHTML = '<div style="background:#fff;border-radius:16px 16px 0 0;width:100%;max-width:480px;padding:20px">' +
    '<div style="font-weight:700;font-size:16px;margin-bottom:16px;color:#1a3560">💡 Suggest Database Change</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px">' + grid + '</div>' +
    '<button onclick="document.getElementById(\'db-suggest-modal\').remove()" style="width:100%;padding:12px;background:#f0f0f0;border:none;border-radius:8px;cursor:pointer">Cancel</button></div>';
  m.onclick = e => { if(e.target===m) m.remove(); };
  document.body.appendChild(m);
}


document.addEventListener('DOMContentLoaded', function() {
  // ── Build core dropdowns (unit, shift, contact) ──────────────────────
  try {
    // UNIT dropdown
    createDropdown({
      id: 'unit',
      container: 'dd-unit',
      items: getEquipmentDB(),
      placeholder: 'Search unit #…',
      displayFn: e => e.unit,
      subFn: e => (e.make||'') + ' ' + (e.model||''),
      onSelect: eq => {
        if (!eq) {
          ['f-make','f-model','f-serial','f-category'].forEach(id => {
            const el = document.getElementById(id); if (el) el.value = '';
          });
          updateReportNumber();
          rfApplyDD && rfApplyDD('unit');
          return;
        }
        const data = eq._custom ? {} : eq;
        document.getElementById('f-make').value     = data.make     || '';
        document.getElementById('f-model').value    = data.model    || '';
        document.getElementById('f-serial').value   = data.serial   || '';
        document.getElementById('f-category').value = data.category || '';
        updateReportNumber();
        if (typeof rfApplyDD === 'function') rfApplyDD('unit');
      }
    });

    // SHIFT dropdown
    createDropdown({
      id: 'shift',
      container: 'dd-shift',
      items: ['501D','501N','502D','502N','503D','503N','504D','504N','505D','505N'],
      placeholder: 'Shift…',
      onSelect: () => { updateReportNumber(); if (typeof rfApplyDD === 'function') rfApplyDD('shift'); }
    });

    // CONTACT dropdown  
    rebuildContactDropdown([], '');

  } catch(e) { console.warn('Dropdown init error:', e.message); }

  // ── Init form ─────────────────────────────────────────────────────────
  try {
    initForm();
  } catch(e) { console.warn('initForm error:', e.message, e.stack); }
  setTimeout(function() {
    try { rfRefreshAll(); rfAttachListeners(); } catch(e) {}
  }, 400);
  try { renderTemplateButtons(); } catch(e) {}
  try { renderPartSetButtons(); } catch(e) {}
  setTimeout(function() {
    initLogin();
    try { initInhausHooks(); } catch(e) {}
    // Init Inhaus default rows
    try {
      if (!document.getElementById('ih-n2-rows')?.hasChildNodes()) {
        ihAddRow('ih-n2-rows','n2');
        ihAddRow('ih-lt30-rows','lt30');
        ihAddRow('ih-inergen-rows','inergen');
        ihAddRow('ih-co2-rows','co2');
        ihAddRow('ih-hose-rows','hose');
        ihAddDryTank();
        ihAddLVSTank();
      }
    } catch(e) {}
    var savedKey = localStorage.getItem('supabase_key');
    if (savedKey && (savedKey.startsWith('eyJ') || savedKey.startsWith('sb_'))) {
      if (typeof initSupabaseWithKey === 'function') {
        initSupabaseWithKey('https://xrstzaybzfseqxwkeotc.supabase.co', savedKey);
      }
    }
  }, 500);
});